const rows=[];const seen=new Set();const plan=$('Plan de busquedas Piura').all();
for(let i=0;i<$input.all().length;i++){
 const r=$input.all()[i].json;
 if(!Array.isArray(r.results))throw new Error('Tavily sin results: revisar credencial, cuota o respuesta');
 const q=plan[i]?.json;if(!q)throw new Error('Consulta sin procedencia');
 if(r.results.length===0){rows.push({json:{record_key:'tavily-empty:'+q.topic+':'+q.query,record_type:'consulta_sin_resultados',topic:q.topic,location_label:'Piura - alcance de busqueda',source_url:'https://api.tavily.com/search',source_date:'',retrieved_at:new Date().toISOString(),quality_status:'sin_resultados_no_equivale_a_ausencia',payload_json:JSON.stringify({query:q.query,request_id:r.request_id})}});continue;}
 for(const hit of r.results){
  if(!hit.url||!hit.url.startsWith('https://'))continue;
  const url=hit.url.split('#')[0];const key=q.topic+'|'+url;if(seen.has(key))continue;seen.add(key);
  rows.push({json:{record_key:'tavily:'+key,record_type:'fuente_descubierta',topic:q.topic,location_label:'Piura - pertinencia espacial pendiente de revision',source_url:url,source_date:hit.published_date||'',retrieved_at:new Date().toISOString(),quality_status:hit.raw_content?'texto_extraido_pendiente_validacion':'fragmento_busqueda_no_hecho_verificado',payload_json:JSON.stringify({title:hit.title,query:q.query,score:hit.score,content:hit.content||'',raw_content:(hit.raw_content||'').slice(0,24000),truncated:(hit.raw_content||'').length>24000,request_id:r.request_id})}});
 }
}
return rows;
